import 'package:kiri_check/kiri_check.dart';

void main() {
  property('FizzBuzz', () {
    forAll(integer(min: 0, max: 100), (n) {
      final result = fizzbuzz(n);
      if (n % 15 == 0) {
        expect(result, 'FizzBuzz');
      } else if (n % 3 == 0) {
        expect(result, 'Fizz');
      } else if (n % 5 == 0) {
        expect(result, 'Buzz');
      } else {
        expect(result, n.toString());
      }
    });
  });
}
